        router.setServerOptions(Optional.ofNullable(BOOT_SERVER).map(Server::getOptions).orElseGet(ServerOptions::new));
    } else {
        copyState(owner, this);
    }
    if (BOOT_SERVER != null) {
        BOOT_SERVER.init(this);
    }
}

